                           "({{ total }}). We'll email you when it ships."),
    "shipped": ("Order {{ order_id }} is on its way",
                "Hi {{ first_name }},\n\nYour order shipped with {{ carrier }}. "
                "Track it here: {{ tracking_url }}"),
    "low_stock": ("Low stock: {{ sku }}", "{{ sku }} is down to {{ available }} units."),
}
